-- ================================================================================================
-- Mill 693 -- owned SOLELY by Schedule5SubPageAuthorizationIT (the 8.2/12.2 lesson: an authorization
-- suite that shares a mill with a functional one starts failing for the wrong reason).
--
-- Its track is deliberately 'S', not 'D'. The "authorized" proof needs authorization to PASS and
-- then something ELSE to stop the write, otherwise it would have to mutate real state to show that
-- 403 was not returned. With a non-Draft track an authorized caller gets 409 from the Draft gate:
-- proof that @PreAuthorize let it through, with nothing written either way.
-- ================================================================================================
INSERT INTO THE.MILL (MILL_ID, MILL_NAME, MILL_NUMBER, ENTRY_USERID) VALUES (693, 'Sch5 SubPage Authz', 693, 'SEED');
